layers.vertex:
attribute vec3 aVertexPosition;
attribute vec2 aTextureCoord;
uniform mat4 uModelMatrix;
uniform mat4 uViewMatrix;
uniform mat4 uProjectionMatrix;
varying float vDepth;
varying vec2 vTextureCoord;
varying vec3 vWorldPos;

void main(void) {
  vec4 world = uModelMatrix * vec4(aVertexPosition, 1.0);
  vec4 v = uViewMatrix * world;
  vDepth = -v.z;
  v.z += 1.2 + vDepth * 0.01;
  vTextureCoord = aTextureCoord;
  vWorldPos = world.xyz;
  gl_Position = uProjectionMatrix * v;
}

layers.fragment:
#extension GL_OES_standard_derivatives : enable

#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform sampler2D uSampler;
uniform vec3 uMaterialDiffuse;
uniform int uHasFog;
uniform vec3 uFogColor;
uniform float uFogNear;
uniform float uFogFar;
varying float vDepth;
varying vec2 vTextureCoord;
varying vec3 vWorldPos;

const vec3 GIRDER_STEEL = vec3(0.0824, 0.1059, 0.1529);
const vec3 OXIDE_STAIN = vec3(0.1098, 0.0784, 0.0627);
const vec3 OXIDE_PIT = vec3(0.0667, 0.0314, 0.0196);
const vec3 OXIDE_DARK = vec3(0.1569, 0.0745, 0.0412);
const vec3 OXIDE_MID = vec3(0.3059, 0.1333, 0.0588);
const vec3 OXIDE_WARM = vec3(0.4667, 0.2078, 0.0784);
const vec3 OXIDE_OCHRE = vec3(0.5765, 0.2784, 0.1020);

uniform int uHasPbr;
uniform sampler2D uNoiseSampler;

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noiseHash(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

// the rust noise: one read of a small tiling noise texture where the surface has material maps, hashed here elsewhere
float noise(vec2 x) {
  if (uHasPbr == 1) {
    vec2 p = floor(x);
    vec2 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return texture2D(uNoiseSampler, (p + f + 0.5) / 256.0).x;
  }
  return noiseHash(x);
}

float fbm(vec2 p) {
  float v = noise(p) * 0.54;
  p = vec2(p.x * 1.62 - p.y * 1.21, p.x * 1.21 + p.y * 1.62) + vec2(17.3, 9.7);
  v += noise(p) * 0.31;
  p = vec2(p.x * 1.58 + p.y * 1.26, -p.x * 1.26 + p.y * 1.58) + vec2(31.1, 23.4);
  v += noise(p) * 0.15;
  return v;
}

uniform int uNbLights;
uniform vec3 uAmbientLight;
uniform vec3 uLightPosition[8];
uniform vec3 uLightDiffuse[8];
uniform vec3 uLightAttenuation[8];

vec3 surfaceLight(vec3 worldPos, float emissive) {
  if (uNbLights <= 0)
    return vec3(1.0);
  vec3 total = uAmbientLight;
  for (int i = 0; i < 8; i++) {
    if (i >= uNbLights)
      break;
    vec3 diff = uLightDiffuse[i];
    if (diff.x + diff.y + diff.z <= 0.001)
      continue;
    vec3 delta = uLightPosition[i] - worldPos;
    if (delta.x * delta.x + delta.z * delta.z > 160000.0)
      continue;
    float isCeilingFixture = step(54.0, uLightPosition[i].y);
    float onCeiling = step(58.0, worldPos.y) * isCeilingFixture;
    float verticalSpan = mix(delta.y, 62.0, onCeiling);
    vec3 lightVec = vec3(delta.x, verticalSpan, delta.z);
    float distSq = dot(lightVec, lightVec);
    if (distSq > 160000.0)
      continue;
    vec3 att = uLightAttenuation[i];
    if (att.z > 0.001 && distSq >= 18225.0)
      continue;
    float dist = sqrt(distSq);
    float shortRange = step(0.001, att.z);
    float rangeCutoff = mix(1.0, 1.0 - smoothstep(75.0, 135.0, dist), shortRange);
    float attenuation = rangeCutoff / max(att.x + att.y * dist + att.z * distSq, 0.0001);
    float downward = clamp((uLightPosition[i].y - worldPos.y) / max(dist, 1.0), 0.0, 1.0);
    float spread = mix(1.05, 0.5 + 0.75 * downward * downward, isCeilingFixture);
    total += diff * (attenuation * spread);
  }
  return mix(min(total, vec3(2.5)), max(total, vec3(1.35)), clamp(emissive, 0.0, 1.0));
}

uniform float uParallax;
uniform sampler2D uNormalSampler;
uniform sampler2D uDetailSampler;
uniform sampler2D uAoSampler;
uniform vec2 uAoInvSize;
uniform vec3 uCameraPosition;

const float PBR_EXPOSURE = 3.0;
const float PARALLAX_DEPTH = 3.0;
const float PARALLAX_CELLS = 8.0;

// the texture coordinate every picture of the surface is read at: the quad's own, or shifted by parallax
vec2 gUv;
vec3 gV;
vec3 gNg;
vec3 gT;
vec3 gB;

float ggxDistribution(float nh, float rough) {
  float a = rough * rough;
  float a2 = a * a;
  float d = nh * nh * (a2 - 1.0) + 1.0;
  return a2 / (3.14159265 * d * d + 0.0001);
}

vec3 filmicTone(vec3 x) {
  return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

/** The view direction, the face normal and the tangent frame of the quad, from how its position and uv change on screen. */
void pbrFrame() {
  vec3 P = vWorldPos;
  gV = normalize(uCameraPosition - P);
  vec3 dpx = dFdx(P);
  vec3 dpy = dFdy(P);
  gNg = normalize(cross(dpx, dpy));
  if (dot(gNg, gV) < 0.0)
    gNg = -gNg;
  vec2 duvx = dFdx(vTextureCoord);
  vec2 duvy = dFdy(vTextureCoord);
  vec3 dp2perp = cross(dpy, gNg);
  vec3 dp1perp = cross(gNg, dpx);
  vec3 T = dp2perp * duvx.x + dp1perp * duvy.x;
  vec3 B = dp2perp * duvx.y + dp1perp * duvy.y;
  float invmax = inversesqrt(max(max(dot(T, T), dot(B, B)), 0.000000000001));
  gT = T * invmax;
  gB = B * invmax;
}

/** Keeps a shifted coordinate inside its own cell of the atlas, so it never reads the neighbouring picture. */
vec2 pbrKeepInCell(vec2 uv) {
  float cell = floor(vTextureCoord.x * PARALLAX_CELLS);
  return vec2(clamp(uv.x, (cell + 0.02) / PARALLAX_CELLS, (cell + 0.98) / PARALLAX_CELLS), clamp(uv.y, 0.004, 0.996));
}

/**
 * Parallax occlusion mapping: walks a ray through the height field (the blue channel of the normal map) in a few steps and
 * returns where it meets the surface, so grooves and plates have depth and shift as you move. It fades out with
 * distance, where the detail is too small to see.
 */
vec2 pbrParallaxUv() {
  pbrFrame();
  float fade = (1.0 - smoothstep(150.0, 380.0, vDepth)) * uParallax;
  if (fade <= 0.001)
    return vTextureCoord;
  vec3 Vt = vec3(dot(gV, gT), dot(gV, gB), max(dot(gV, gNg), 0.25));
  vec2 uvPerUnit = vec2(1.0 / (64.0 * PARALLAX_CELLS), 1.0 / 64.0);
  vec2 delta = (Vt.xy / Vt.z) * (PARALLAX_DEPTH * fade) * uvPerUnit / 4.0;
  vec2 uv = vTextureCoord;
  float cur = 0.0;
  float hd = 1.0 - texture2D(uNormalSampler, uv).b;
  vec2 prevUv = uv;
  float prevCur = 0.0;
  float prevHd = hd;
  for (int i = 0; i < 4; i++) {
    float go = step(cur, hd);
    prevUv = mix(prevUv, uv, go);
    prevCur = mix(prevCur, cur, go);
    prevHd = mix(prevHd, hd, go);
    uv = pbrKeepInCell(uv - delta * go);
    cur += go / 4.0;
    hd = 1.0 - texture2D(uNormalSampler, uv).b;
  }
  float after = hd - cur;
  float before = prevHd - prevCur;
  float w = clamp(after / (after - before - 0.00001), 0.0, 1.0);
  return mix(uv, prevUv, w);
}

/**
 * Ambient occlusion from the plan of the level, baked into a small map (R: solid share within ~16 units, G: within ~48).
 * A floor or ceiling darkens where it meets a wall; a wall darkens in concave corners and down by the floor and up by
 * the ceiling. This is the contact shading the flat quads cannot show by themselves.
 */
float levelOcclusion(vec3 P, vec3 Ng) {
  float flatSurface = step(0.7, abs(Ng.y));
  // one read: at the point itself for a floor or ceiling, a little way out from the wall for a wall
  vec2 q = mix(P.xz + Ng.xz * 10.0, P.xz, flatSurface);
  vec2 ao = texture2D(uAoSampler, q * uAoInvSize).rg;
  float contact = 1.0 - clamp(ao.r * 0.95, 0.0, 0.7);
  float corner = 1.0 - clamp((ao.g - 0.42) * 2.4, 0.0, 0.62);
  float low = mix(0.6, 1.0, smoothstep(0.0, 18.0, P.y));
  float high = mix(0.72, 1.0, smoothstep(63.0, 46.0, P.y));
  return mix(corner * low * high, contact, flatSurface);
}

/**
 * Physically based shading of a wall, floor or ceiling with a normal map (its blue is the height, its alpha the baked AO); roughness and metalness come from the colour and the height.
 * The light list, ranges and falloff are those of surfaceLight; what changes is how a light meets the surface: its
 * direction against the mapped normal, a GGX highlight, and a filmic curve at the end. `rustiness` (0..1) makes a
 * pixel rougher and less metallic, so rust is matte and bare steel shines. Returns a display colour.
 */
vec3 pbrShade(vec3 albedoSrgb, float emissive, float rustiness) {
  vec3 P = vWorldPos;
  vec3 V = gV;
  vec3 Ng = gNg;
  vec4 nm = texture2D(uNormalSampler, gUv);
  vec3 nt = vec3(nm.xy * 2.0 - 1.0, 0.0);
  nt.z = sqrt(max(0.0, 1.0 - dot(nt.xy, nt.xy)));
  // fine grain over the baked relief, in world space, near the camera only
  float detailFade = 1.0 - smoothstep(180.0, 520.0, vDepth);
  if (detailFade > 0.001) {
    vec2 dn = texture2D(uDetailSampler, vec2(dot(P, gT), dot(P, gB)) / 24.0).xy * 2.0 - 1.0;
    nt = normalize(vec3(nt.xy + dn * 0.14 * detailFade, nt.z));
  }
  vec3 N = normalize(gT * nt.x + gB * nt.y + Ng * nt.z);
  float ao = nm.a;
  // sunk places are rougher, raised edges smoother; painted (warm) and rusted places are matte and not metal
  float hh = (nm.b - 0.75) * 8.0;
  float warm = clamp((albedoSrgb.r - albedoSrgb.b) * 2.83, 0.0, 1.0);
  float glow = clamp((max(albedoSrgb.b, albedoSrgb.g) - albedoSrgb.r) * 3.64, 0.0, 1.0);
  float rough = clamp(mix(0.5 - 0.14 * clamp(hh, 0.0, 1.6) + 0.18 * clamp(-hh, 0.0, 1.7) + warm * 0.2, 0.92, rustiness), 0.08, 1.0);
  float metal = clamp(0.9 - warm * 0.8 - glow * 0.5, 0.05, 0.95) * (1.0 - rustiness * 0.9);
  vec3 a0 = max(albedoSrgb, vec3(0.0));
  vec3 albedo = a0 * (a0 * (a0 * 0.305306011 + 0.682171111) + 0.012522878);
  vec3 F0 = mix(vec3(0.04), min(albedo * 2.0 + 0.03, vec3(0.6)), metal);
  vec3 diffuseColor = albedo * (1.0 - 0.5 * metal);
  float NV = max(dot(N, V), 0.02);
  float k = (rough + 1.0) * (rough + 1.0) * 0.125;
  float onCeiling = step(58.0, P.y);
  float occlusion = levelOcclusion(P, Ng);
  float sky = N.y * 0.5 + 0.5;
  vec3 irradiance = uAmbientLight * 0.85 * ao * occlusion * (0.55 + 0.45 * sky);
  vec3 diffuseAcc = vec3(0.0);
  vec3 specAcc = vec3(0.0);
  if (uNbLights > 0) {
    for (int i = 0; i < 8; i++) {
      if (i >= uNbLights)
        break;
      vec3 diff = uLightDiffuse[i];
      if (diff.x + diff.y + diff.z <= 0.001)
        continue;
      vec3 delta = uLightPosition[i] - P;
      if (delta.x * delta.x + delta.z * delta.z > 160000.0)
        continue;
      float isCeilingFixture = step(54.0, uLightPosition[i].y);
      float fixtureCeiling = onCeiling * isCeilingFixture;
      float verticalSpan = mix(delta.y, 62.0, fixtureCeiling);
      vec3 lightVec = vec3(delta.x, verticalSpan, delta.z);
      float distSq = dot(lightVec, lightVec);
      if (distSq > 160000.0)
        continue;
      vec3 att = uLightAttenuation[i];
      if (att.z > 0.001 && distSq >= 18225.0)
        continue;
      float dist = sqrt(distSq);
      float shortRange = step(0.001, att.z);
      float rangeCutoff = mix(1.0, 1.0 - smoothstep(75.0, 135.0, dist), shortRange);
      float attenuation = rangeCutoff / max(att.x + att.y * dist + att.z * distSq, 0.0001);
      float downward = clamp((uLightPosition[i].y - P.y) / max(dist, 1.0), 0.0, 1.0);
      float spread = mix(1.05, 0.5 + 0.75 * downward * downward, isCeilingFixture);
      vec3 lc = diff * (attenuation * spread);
      // a ceiling is lit by the glow of the room below it: take the light as coming from under it
      vec3 L = normalize(vec3(delta.x, mix(delta.y, -62.0, onCeiling), delta.z));
      // real N.L, a little wrapped: a surface turned away from a light is darker, so edges and bumps read
      float wrapN = clamp(dot(N, L) * 0.85 + 0.15, 0.0, 1.0);
      diffuseAcc += lc * (wrapN * occlusion);
      // the highlight only for the 4 nearest lights (the list is sorted by distance to the camera)
      if (i < 4) {
        float NL = max(dot(N, L), 0.0);
        vec3 H = normalize(L + V);
        float NH = max(dot(N, H), 0.0);
        float fv = 1.0 - max(dot(V, H), 0.0);
        float fv2 = fv * fv;
        float G = (NL / (NL * (1.0 - k) + k)) * (NV / (NV * (1.0 - k) + k));
        vec3 F = F0 + (1.0 - F0) * (fv2 * fv2 * fv);
        specAcc += lc * F * (ggxDistribution(NH, rough) * G / (4.0 * NV)) * (0.55 * step(0.0, dot(Ng, L)));
      }
    }
  }
  vec3 lightTotal = min(irradiance + diffuseAcc * mix(1.0, ao, 0.6), vec3(2.5));
  // what a shiny surface mirrors of the room: mostly the lit ceiling above, little from the floor
  vec3 R = reflect(-V, N);
  float fn = 1.0 - NV;
  float fn2 = fn * fn;
  vec3 Fenv = F0 + (max(vec3(1.0 - rough), F0) - F0) * (fn2 * fn2 * fn);
  float envUp = mix(0.3, 1.0, smoothstep(-0.2, 0.8, R.y));
  vec3 envSpec = Fenv * uAmbientLight * envUp * ao * occlusion * 0.1;
  vec3 colorLin = diffuseColor * lightTotal + specAcc * ao + envSpec;
  colorLin += albedo * emissive * 1.8;
  vec3 mapped = filmicTone(colorLin * PBR_EXPOSURE);
  return pow(mapped, vec3(0.4545));
}


void main(void) {
  gUv = uHasPbr == 1 ? pbrParallaxUv() : vTextureCoord;
  vec4 texel = texture2D(uSampler, gUv);
  if (texel.a < 0.5)
    discard;
  if (uHasFog == 1 && vDepth >= uFogFar) {
    gl_FragColor = vec4(uFogColor, 0.5);
    return;
  }
  vec3 base = texel.rgb;
  float cyanGlow = smoothstep(0.08, 0.25, max(base.b, base.g) - base.r);
  float amberGlow = smoothstep(0.18, 0.42, base.r - base.b) * smoothstep(0.28, 0.55, base.g);
  float lit = clamp(max(cyanGlow, amberGlow * 0.75), 0.0, 1.0);
  float isCeiling = step(58.0, vWorldPos.y);
  float rustiness = 0.0;
  vec2 tileUv = fract(vWorldPos.xz / 64.0);
  vec2 borderDist = min(tileUv, 1.0 - tileUv);
  float minBorder = min(borderDist.x, borderDist.y);
  float edgeGirder = 1.0 - smoothstep(0.0, 0.11, minBorder);
  float recessWell = smoothstep(0.14, 0.34, minBorder);
  vec3 overheadTint = mix(vec3(0.88, 0.94, 1.04), vec3(0.68, 0.75, 0.88), recessWell * (1.0 - lit));
  vec3 ceilingColor = base * overheadTint * (1.0 - edgeGirder * 0.22 * (1.0 - lit));
  if (isCeiling > 0.5 && lit < 0.92 && base.b >= base.r - 0.03) {
    vec2 p = vec2(vWorldPos.x * 1.03 + vWorldPos.z * 0.07, vWorldPos.z * 0.97 - vWorldPos.x * 0.07);
    float scale = 21.0;
    vec2 texelPos = floor(p * 4.0) * 0.25;
    float g1 = noise(texelPos / 2.1 + 15.0);
    float g2 = noise(texelPos / 0.85 + 47.0);
    float grain = g1 * 0.52 + g2 * 0.48;
    vec2 jitter = vec2(
      noise(p / 3.8 + vec2(19.3, 7.1)) - 0.5,
      noise(p / 3.8 + vec2(37.9, 23.4)) - 0.5
    ) * 2.1 + vec2(g1 - 0.5, g2 - 0.5) * 0.9;
    vec2 pw = p + jitter;
    float coarse = fbm(pw / scale + 31.0);
    float fineA = noise(vec2(pw.x / (scale * 0.38) - pw.y / (scale * 0.51) + 13.0, pw.y / (scale * 0.38) + pw.x / (scale * 0.51) + 41.0));
    float fineB = 1.0 - abs(noise(vec2(pw.x / (scale * 0.21) + pw.y / (scale * 0.29) + 59.0, pw.y / (scale * 0.21) - pw.x / (scale * 0.29) + 89.0)) * 2.0 - 1.0);
    float spots = coarse * 0.40 + fineA * 0.30 + fineB * 0.18 + grain * 0.12;
    if (spots > 0.49) {
      float thresh = 0.64;
      float patchGate = smoothstep(thresh - 0.06, thresh + 0.03, spots);
      float cofferLip = 1.0 - smoothstep(0.0, 0.038, abs(minBorder - 0.125));
      float cornerPocket = (1.0 - smoothstep(0.0, 0.18, borderDist.x)) * (1.0 - smoothstep(0.0, 0.18, borderDist.y));
      float baseLum = dot(base, vec3(0.299, 0.587, 0.114));
      float crevice = clamp((0.115 - baseLum) * 6.0, 0.0, 1.0);
      float ridge = clamp((baseLum - 0.13) * 4.5, 0.0, 1.0);
      float seamBoost = (edgeGirder * 0.16 + cofferLip * 0.18 + cornerPocket * 0.18 + crevice * 0.12) * smoothstep(0.45, 0.78, fineA * 0.60 + grain * 0.40);
      float area = smoothstep(thresh, thresh + 0.10, spots + crevice * 0.03 * patchGate - ridge * 0.04);
      area = clamp(area + seamBoost * 0.65 * patchGate, 0.0, 1.0);
      float near = 1.0 - smoothstep(220.0, 640.0, vDepth);
      float bump = 0.0;
      if (near > 0.01 && area > 0.08) {
        float gShift = noise((texelPos + vec2(0.25, -0.25)) / 1.15 + 47.0);
        bump = (g2 - gShift) * near;
      }
      float edgeBreak = smoothstep(0.26, 0.74, grain * 0.58 + fineB * 0.42);
      float breakup = mix(0.62 * edgeBreak, (0.20 + grain * 0.94 + crevice * 0.18 - ridge * 0.16) * (0.40 + 0.60 * edgeBreak), near);
      float amount = clamp(area * breakup * 1.22 * (1.0 - lit), 0.0, 1.0);
      float stain = smoothstep(0.08, 0.31, amount * 0.75 + area * edgeBreak * 0.25) * (1.0 - lit);
      float flake = smoothstep(0.65, 0.90, grain) * smoothstep(0.50, 0.84, amount) * near;
      float pit = smoothstep(0.39, 0.15, grain) * smoothstep(0.68, 0.94, amount + crevice * 0.22) * near;
      rustiness = clamp(stain * 0.4 + amount, 0.0, 1.0);
      if (stain > 0.01) {
        vec3 steelDetail = ceilingColor - GIRDER_STEEL;
        vec3 stained = clamp(mix(GIRDER_STEEL, OXIDE_STAIN, 0.56) + steelDetail * 0.84, 0.0, 1.0);
        ceilingColor = mix(ceilingColor, stained, stain * 0.27);
        if (amount > 0.16) {
          vec3 oxide = mix(OXIDE_DARK, OXIDE_MID, smoothstep(0.22, 0.62, amount));
          oxide = mix(oxide, OXIDE_WARM, smoothstep(0.58, 0.90, amount));
          oxide = mix(oxide, OXIDE_OCHRE, flake * 0.62);
          oxide = mix(oxide, OXIDE_PIT, pit * 0.76);
          float relief = bump * (0.07 + 0.07 * amount);
          float keepSteel = mix(0.74, 0.28, smoothstep(0.20, 0.88, amount));
          vec3 corroded = clamp(oxide + steelDetail * keepSteel + vec3(1.0, 0.58, 0.28) * relief, 0.0, 1.0);
          float rustBlend = smoothstep(0.16, 0.42, amount) * clamp(0.32 + amount * 0.58, 0.0, 1.0);
          ceilingColor = mix(ceilingColor, corroded, rustBlend);
        }
      }
    }
  }
  vec3 color = mix(base, ceilingColor, isCeiling);
  if (uHasPbr == 1)
    color = pbrShade(color * uMaterialDiffuse, lit, rustiness);
  else
    color *= uMaterialDiffuse * surfaceLight(vWorldPos, lit);
  color += vec3(0.04, 0.18, 0.24) * cyanGlow * (1.0 - isCeiling) * 0.45;
  float pitDepthFade = smoothstep(-2.0, -48.0, vWorldPos.y);
  vec3 pitFogColor = uHasFog == 1 ? uFogColor * 0.42 : vec3(0.02, 0.03, 0.06);
  color = mix(color, pitFogColor, pitDepthFade);
  if (uHasFog == 1) {
    float fade = clamp((vDepth - uFogNear) / (uFogFar - uFogNear), 0.0, 1.0);
    color = mix(color, uFogColor, fade);
  }
  gl_FragColor = vec4(color, 0.5);
}

vertex:
attribute vec3 aVertexPosition;
attribute vec2 aTextureCoord;
uniform mat4 uModelMatrix;
uniform mat4 uViewMatrix;
uniform mat4 uProjectionMatrix;
varying float vDepth;
varying vec2 vTextureCoord;
varying vec3 vWorldPos;

void main(void) {
  vec4 world = uModelMatrix * vec4(aVertexPosition, 1.0);
  vec4 v = uViewMatrix * world;
  vDepth = -v.z;
  v.z += 1.2 + vDepth * 0.01;
  vTextureCoord = aTextureCoord;
  vWorldPos = world.xyz;
  gl_Position = uProjectionMatrix * v;
}

fragment:
#extension GL_OES_standard_derivatives : enable

#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif
uniform sampler2D uSampler;
uniform vec3 uMaterialDiffuse;
uniform int uHasFog;
uniform vec3 uFogColor;
uniform float uFogNear;
uniform float uFogFar;
varying float vDepth;
varying vec2 vTextureCoord;
varying vec3 vWorldPos;

const vec3 GIRDER_STEEL = vec3(0.0824, 0.1059, 0.1529);
const vec3 OXIDE_STAIN = vec3(0.1098, 0.0784, 0.0627);
const vec3 OXIDE_PIT = vec3(0.0667, 0.0314, 0.0196);
const vec3 OXIDE_DARK = vec3(0.1569, 0.0745, 0.0412);
const vec3 OXIDE_MID = vec3(0.3059, 0.1333, 0.0588);
const vec3 OXIDE_WARM = vec3(0.4667, 0.2078, 0.0784);
const vec3 OXIDE_OCHRE = vec3(0.5765, 0.2784, 0.1020);

uniform int uHasPbr;
uniform sampler2D uNoiseSampler;

float hash(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}

float noiseHash(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

// the rust noise: one read of a small tiling noise texture where the surface has material maps, hashed here elsewhere
float noise(vec2 x) {
  if (uHasPbr == 1) {
    vec2 p = floor(x);
    vec2 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return texture2D(uNoiseSampler, (p + f + 0.5) / 256.0).x;
  }
  return noiseHash(x);
}

float fbm(vec2 p) {
  float v = noise(p) * 0.54;
  p = vec2(p.x * 1.62 - p.y * 1.21, p.x * 1.21 + p.y * 1.62) + vec2(17.3, 9.7);
  v += noise(p) * 0.31;
  p = vec2(p.x * 1.58 + p.y * 1.26, -p.x * 1.26 + p.y * 1.58) + vec2(31.1, 23.4);
  v += noise(p) * 0.15;
  return v;
}

uniform int uNbLights;
uniform vec3 uAmbientLight;
uniform vec3 uLightPosition[8];
uniform vec3 uLightDiffuse[8];
uniform vec3 uLightAttenuation[8];

vec3 surfaceLight(vec3 worldPos, float emissive) {
  if (uNbLights <= 0)
    return vec3(1.0);
  vec3 total = uAmbientLight;
  for (int i = 0; i < 8; i++) {
    if (i >= uNbLights)
      break;
    vec3 diff = uLightDiffuse[i];
    if (diff.x + diff.y + diff.z <= 0.001)
      continue;
    vec3 delta = uLightPosition[i] - worldPos;
    if (delta.x * delta.x + delta.z * delta.z > 160000.0)
      continue;
    float isCeilingFixture = step(54.0, uLightPosition[i].y);
    float onCeiling = step(58.0, worldPos.y) * isCeilingFixture;
    float verticalSpan = mix(delta.y, 62.0, onCeiling);
    vec3 lightVec = vec3(delta.x, verticalSpan, delta.z);
    float distSq = dot(lightVec, lightVec);
    if (distSq > 160000.0)
      continue;
    vec3 att = uLightAttenuation[i];
    if (att.z > 0.001 && distSq >= 18225.0)
      continue;
    float dist = sqrt(distSq);
    float shortRange = step(0.001, att.z);
    float rangeCutoff = mix(1.0, 1.0 - smoothstep(75.0, 135.0, dist), shortRange);
    float attenuation = rangeCutoff / max(att.x + att.y * dist + att.z * distSq, 0.0001);
    float downward = clamp((uLightPosition[i].y - worldPos.y) / max(dist, 1.0), 0.0, 1.0);
    float spread = mix(1.05, 0.5 + 0.75 * downward * downward, isCeilingFixture);
    total += diff * (attenuation * spread);
  }
  return mix(min(total, vec3(2.5)), max(total, vec3(1.35)), clamp(emissive, 0.0, 1.0));
}

uniform float uParallax;
uniform sampler2D uNormalSampler;
uniform sampler2D uDetailSampler;
uniform sampler2D uAoSampler;
uniform vec2 uAoInvSize;
uniform vec3 uCameraPosition;

const float PBR_EXPOSURE = 3.0;
const float PARALLAX_DEPTH = 3.0;
const float PARALLAX_CELLS = 8.0;

// the texture coordinate every picture of the surface is read at: the quad's own, or shifted by parallax
vec2 gUv;
vec3 gV;
vec3 gNg;
vec3 gT;
vec3 gB;

float ggxDistribution(float nh, float rough) {
  float a = rough * rough;
  float a2 = a * a;
  float d = nh * nh * (a2 - 1.0) + 1.0;
  return a2 / (3.14159265 * d * d + 0.0001);
}

vec3 filmicTone(vec3 x) {
  return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

/** The view direction, the face normal and the tangent frame of the quad, from how its position and uv change on screen. */
void pbrFrame() {
  vec3 P = vWorldPos;
  gV = normalize(uCameraPosition - P);
  vec3 dpx = dFdx(P);
  vec3 dpy = dFdy(P);
  gNg = normalize(cross(dpx, dpy));
  if (dot(gNg, gV) < 0.0)
    gNg = -gNg;
  vec2 duvx = dFdx(vTextureCoord);
  vec2 duvy = dFdy(vTextureCoord);
  vec3 dp2perp = cross(dpy, gNg);
  vec3 dp1perp = cross(gNg, dpx);
  vec3 T = dp2perp * duvx.x + dp1perp * duvy.x;
  vec3 B = dp2perp * duvx.y + dp1perp * duvy.y;
  float invmax = inversesqrt(max(max(dot(T, T), dot(B, B)), 0.000000000001));
  gT = T * invmax;
  gB = B * invmax;
}

/** Keeps a shifted coordinate inside its own cell of the atlas, so it never reads the neighbouring picture. */
vec2 pbrKeepInCell(vec2 uv) {
  float cell = floor(vTextureCoord.x * PARALLAX_CELLS);
  return vec2(clamp(uv.x, (cell + 0.02) / PARALLAX_CELLS, (cell + 0.98) / PARALLAX_CELLS), clamp(uv.y, 0.004, 0.996));
}

/**
 * Parallax occlusion mapping: walks a ray through the height field (the blue channel of the normal map) in a few steps and
 * returns where it meets the surface, so grooves and plates have depth and shift as you move. It fades out with
 * distance, where the detail is too small to see.
 */
vec2 pbrParallaxUv() {
  pbrFrame();
  float fade = (1.0 - smoothstep(150.0, 380.0, vDepth)) * uParallax;
  if (fade <= 0.001)
    return vTextureCoord;
  vec3 Vt = vec3(dot(gV, gT), dot(gV, gB), max(dot(gV, gNg), 0.25));
  vec2 uvPerUnit = vec2(1.0 / (64.0 * PARALLAX_CELLS), 1.0 / 64.0);
  vec2 delta = (Vt.xy / Vt.z) * (PARALLAX_DEPTH * fade) * uvPerUnit / 4.0;
  vec2 uv = vTextureCoord;
  float cur = 0.0;
  float hd = 1.0 - texture2D(uNormalSampler, uv).b;
  vec2 prevUv = uv;
  float prevCur = 0.0;
  float prevHd = hd;
  for (int i = 0; i < 4; i++) {
    float go = step(cur, hd);
    prevUv = mix(prevUv, uv, go);
    prevCur = mix(prevCur, cur, go);
    prevHd = mix(prevHd, hd, go);
    uv = pbrKeepInCell(uv - delta * go);
    cur += go / 4.0;
    hd = 1.0 - texture2D(uNormalSampler, uv).b;
  }
  float after = hd - cur;
  float before = prevHd - prevCur;
  float w = clamp(after / (after - before - 0.00001), 0.0, 1.0);
  return mix(uv, prevUv, w);
}

/**
 * Ambient occlusion from the plan of the level, baked into a small map (R: solid share within ~16 units, G: within ~48).
 * A floor or ceiling darkens where it meets a wall; a wall darkens in concave corners and down by the floor and up by
 * the ceiling. This is the contact shading the flat quads cannot show by themselves.
 */
float levelOcclusion(vec3 P, vec3 Ng) {
  float flatSurface = step(0.7, abs(Ng.y));
  // one read: at the point itself for a floor or ceiling, a little way out from the wall for a wall
  vec2 q = mix(P.xz + Ng.xz * 10.0, P.xz, flatSurface);
  vec2 ao = texture2D(uAoSampler, q * uAoInvSize).rg;
  float contact = 1.0 - clamp(ao.r * 0.95, 0.0, 0.7);
  float corner = 1.0 - clamp((ao.g - 0.42) * 2.4, 0.0, 0.62);
  float low = mix(0.6, 1.0, smoothstep(0.0, 18.0, P.y));
  float high = mix(0.72, 1.0, smoothstep(63.0, 46.0, P.y));
  return mix(corner * low * high, contact, flatSurface);
}

/**
 * Physically based shading of a wall, floor or ceiling with a normal map (its blue is the height, its alpha the baked AO); roughness and metalness come from the colour and the height.
 * The light list, ranges and falloff are those of surfaceLight; what changes is how a light meets the surface: its
 * direction against the mapped normal, a GGX highlight, and a filmic curve at the end. `rustiness` (0..1) makes a
 * pixel rougher and less metallic, so rust is matte and bare steel shines. Returns a display colour.
 */
vec3 pbrShade(vec3 albedoSrgb, float emissive, float rustiness) {
  vec3 P = vWorldPos;
  vec3 V = gV;
  vec3 Ng = gNg;
  vec4 nm = texture2D(uNormalSampler, gUv);
  vec3 nt = vec3(nm.xy * 2.0 - 1.0, 0.0);
  nt.z = sqrt(max(0.0, 1.0 - dot(nt.xy, nt.xy)));
  // fine grain over the baked relief, in world space, near the camera only
  float detailFade = 1.0 - smoothstep(180.0, 520.0, vDepth);
  if (detailFade > 0.001) {
    vec2 dn = texture2D(uDetailSampler, vec2(dot(P, gT), dot(P, gB)) / 24.0).xy * 2.0 - 1.0;
    nt = normalize(vec3(nt.xy + dn * 0.14 * detailFade, nt.z));
  }
  vec3 N = normalize(gT * nt.x + gB * nt.y + Ng * nt.z);
  float ao = nm.a;
  // sunk places are rougher, raised edges smoother; painted (warm) and rusted places are matte and not metal
  float hh = (nm.b - 0.75) * 8.0;
  float warm = clamp((albedoSrgb.r - albedoSrgb.b) * 2.83, 0.0, 1.0);
  float glow = clamp((max(albedoSrgb.b, albedoSrgb.g) - albedoSrgb.r) * 3.64, 0.0, 1.0);
  float rough = clamp(mix(0.5 - 0.14 * clamp(hh, 0.0, 1.6) + 0.18 * clamp(-hh, 0.0, 1.7) + warm * 0.2, 0.92, rustiness), 0.08, 1.0);
  float metal = clamp(0.9 - warm * 0.8 - glow * 0.5, 0.05, 0.95) * (1.0 - rustiness * 0.9);
  vec3 a0 = max(albedoSrgb, vec3(0.0));
  vec3 albedo = a0 * (a0 * (a0 * 0.305306011 + 0.682171111) + 0.012522878);
  vec3 F0 = mix(vec3(0.04), min(albedo * 2.0 + 0.03, vec3(0.6)), metal);
  vec3 diffuseColor = albedo * (1.0 - 0.5 * metal);
  float NV = max(dot(N, V), 0.02);
  float k = (rough + 1.0) * (rough + 1.0) * 0.125;
  float onCeiling = step(58.0, P.y);
  float occlusion = levelOcclusion(P, Ng);
  float sky = N.y * 0.5 + 0.5;
  vec3 irradiance = uAmbientLight * 0.85 * ao * occlusion * (0.55 + 0.45 * sky);
  vec3 diffuseAcc = vec3(0.0);
  vec3 specAcc = vec3(0.0);
  if (uNbLights > 0) {
    for (int i = 0; i < 8; i++) {
      if (i >= uNbLights)
        break;
      vec3 diff = uLightDiffuse[i];
      if (diff.x + diff.y + diff.z <= 0.001)
        continue;
      vec3 delta = uLightPosition[i] - P;
      if (delta.x * delta.x + delta.z * delta.z > 160000.0)
        continue;
      float isCeilingFixture = step(54.0, uLightPosition[i].y);
      float fixtureCeiling = onCeiling * isCeilingFixture;
      float verticalSpan = mix(delta.y, 62.0, fixtureCeiling);
      vec3 lightVec = vec3(delta.x, verticalSpan, delta.z);
      float distSq = dot(lightVec, lightVec);
      if (distSq > 160000.0)
        continue;
      vec3 att = uLightAttenuation[i];
      if (att.z > 0.001 && distSq >= 18225.0)
        continue;
      float dist = sqrt(distSq);
      float shortRange = step(0.001, att.z);
      float rangeCutoff = mix(1.0, 1.0 - smoothstep(75.0, 135.0, dist), shortRange);
      float attenuation = rangeCutoff / max(att.x + att.y * dist + att.z * distSq, 0.0001);
      float downward = clamp((uLightPosition[i].y - P.y) / max(dist, 1.0), 0.0, 1.0);
      float spread = mix(1.05, 0.5 + 0.75 * downward * downward, isCeilingFixture);
      vec3 lc = diff * (attenuation * spread);
      // a ceiling is lit by the glow of the room below it: take the light as coming from under it
      vec3 L = normalize(vec3(delta.x, mix(delta.y, -62.0, onCeiling), delta.z));
      // real N.L, a little wrapped: a surface turned away from a light is darker, so edges and bumps read
      float wrapN = clamp(dot(N, L) * 0.85 + 0.15, 0.0, 1.0);
      diffuseAcc += lc * (wrapN * occlusion);
      // the highlight only for the 4 nearest lights (the list is sorted by distance to the camera)
      if (i < 4) {
        float NL = max(dot(N, L), 0.0);
        vec3 H = normalize(L + V);
        float NH = max(dot(N, H), 0.0);
        float fv = 1.0 - max(dot(V, H), 0.0);
        float fv2 = fv * fv;
        float G = (NL / (NL * (1.0 - k) + k)) * (NV / (NV * (1.0 - k) + k));
        vec3 F = F0 + (1.0 - F0) * (fv2 * fv2 * fv);
        specAcc += lc * F * (ggxDistribution(NH, rough) * G / (4.0 * NV)) * (0.55 * step(0.0, dot(Ng, L)));
      }
    }
  }
  vec3 lightTotal = min(irradiance + diffuseAcc * mix(1.0, ao, 0.6), vec3(2.5));
  // what a shiny surface mirrors of the room: mostly the lit ceiling above, little from the floor
  vec3 R = reflect(-V, N);
  float fn = 1.0 - NV;
  float fn2 = fn * fn;
  vec3 Fenv = F0 + (max(vec3(1.0 - rough), F0) - F0) * (fn2 * fn2 * fn);
  float envUp = mix(0.3, 1.0, smoothstep(-0.2, 0.8, R.y));
  vec3 envSpec = Fenv * uAmbientLight * envUp * ao * occlusion * 0.1;
  vec3 colorLin = diffuseColor * lightTotal + specAcc * ao + envSpec;
  colorLin += albedo * emissive * 1.8;
  vec3 mapped = filmicTone(colorLin * PBR_EXPOSURE);
  return pow(mapped, vec3(0.4545));
}


void main(void) {
  gUv = uHasPbr == 1 ? pbrParallaxUv() : vTextureCoord;
  vec4 texel = texture2D(uSampler, gUv);
  if (texel.a < 0.5)
    discard;
  if (uHasFog == 1 && vDepth >= uFogFar) {
    gl_FragColor = vec4(uFogColor, 0.5);
    return;
  }
  vec3 base = texel.rgb;
  float cyanGlow = smoothstep(0.08, 0.25, max(base.b, base.g) - base.r);
  float amberGlow = smoothstep(0.18, 0.42, base.r - base.b) * smoothstep(0.28, 0.55, base.g);
  float lit = clamp(max(cyanGlow, amberGlow * 0.75), 0.0, 1.0);
  float isCeiling = step(58.0, vWorldPos.y);
  float rustiness = 0.0;
  vec2 tileUv = fract(vWorldPos.xz / 64.0);
  vec2 borderDist = min(tileUv, 1.0 - tileUv);
  float minBorder = min(borderDist.x, borderDist.y);
  float edgeGirder = 1.0 - smoothstep(0.0, 0.11, minBorder);
  float recessWell = smoothstep(0.14, 0.34, minBorder);
  vec3 overheadTint = mix(vec3(0.88, 0.94, 1.04), vec3(0.68, 0.75, 0.88), recessWell * (1.0 - lit));
  vec3 ceilingColor = base * overheadTint * (1.0 - edgeGirder * 0.22 * (1.0 - lit));
  if (isCeiling > 0.5 && lit < 0.92 && base.b >= base.r - 0.03) {
    vec2 p = vec2(vWorldPos.x * 1.03 + vWorldPos.z * 0.07, vWorldPos.z * 0.97 - vWorldPos.x * 0.07);
    float scale = 21.0;
    vec2 texelPos = floor(p * 4.0) * 0.25;
    float g1 = noise(texelPos / 2.1 + 15.0);
    float g2 = noise(texelPos / 0.85 + 47.0);
    float grain = g1 * 0.52 + g2 * 0.48;
    vec2 jitter = vec2(
      noise(p / 3.8 + vec2(19.3, 7.1)) - 0.5,
      noise(p / 3.8 + vec2(37.9, 23.4)) - 0.5
    ) * 2.1 + vec2(g1 - 0.5, g2 - 0.5) * 0.9;
    vec2 pw = p + jitter;
    float coarse = fbm(pw / scale + 31.0);
    float fineA = noise(vec2(pw.x / (scale * 0.38) - pw.y / (scale * 0.51) + 13.0, pw.y / (scale * 0.38) + pw.x / (scale * 0.51) + 41.0));
    float fineB = 1.0 - abs(noise(vec2(pw.x / (scale * 0.21) + pw.y / (scale * 0.29) + 59.0, pw.y / (scale * 0.21) - pw.x / (scale * 0.29) + 89.0)) * 2.0 - 1.0);
    float spots = coarse * 0.40 + fineA * 0.30 + fineB * 0.18 + grain * 0.12;
    if (spots > 0.49) {
      float thresh = 0.64;
      float patchGate = smoothstep(thresh - 0.06, thresh + 0.03, spots);
      float cofferLip = 1.0 - smoothstep(0.0, 0.038, abs(minBorder - 0.125));
      float cornerPocket = (1.0 - smoothstep(0.0, 0.18, borderDist.x)) * (1.0 - smoothstep(0.0, 0.18, borderDist.y));
      float baseLum = dot(base, vec3(0.299, 0.587, 0.114));
      float crevice = clamp((0.115 - baseLum) * 6.0, 0.0, 1.0);
      float ridge = clamp((baseLum - 0.13) * 4.5, 0.0, 1.0);
      float seamBoost = (edgeGirder * 0.16 + cofferLip * 0.18 + cornerPocket * 0.18 + crevice * 0.12) * smoothstep(0.45, 0.78, fineA * 0.60 + grain * 0.40);
      float area = smoothstep(thresh, thresh + 0.10, spots + crevice * 0.03 * patchGate - ridge * 0.04);
      area = clamp(area + seamBoost * 0.65 * patchGate, 0.0, 1.0);
      float near = 1.0 - smoothstep(220.0, 640.0, vDepth);
      float bump = 0.0;
      if (near > 0.01 && area > 0.08) {
        float gShift = noise((texelPos + vec2(0.25, -0.25)) / 1.15 + 47.0);
        bump = (g2 - gShift) * near;
      }
      float edgeBreak = smoothstep(0.26, 0.74, grain * 0.58 + fineB * 0.42);
      float breakup = mix(0.62 * edgeBreak, (0.20 + grain * 0.94 + crevice * 0.18 - ridge * 0.16) * (0.40 + 0.60 * edgeBreak), near);
      float amount = clamp(area * breakup * 1.22 * (1.0 - lit), 0.0, 1.0);
      float stain = smoothstep(0.08, 0.31, amount * 0.75 + area * edgeBreak * 0.25) * (1.0 - lit);
      float flake = smoothstep(0.65, 0.90, grain) * smoothstep(0.50, 0.84, amount) * near;
      float pit = smoothstep(0.39, 0.15, grain) * smoothstep(0.68, 0.94, amount + crevice * 0.22) * near;
      rustiness = clamp(stain * 0.4 + amount, 0.0, 1.0);
      if (stain > 0.01) {
        vec3 steelDetail = ceilingColor - GIRDER_STEEL;
        vec3 stained = clamp(mix(GIRDER_STEEL, OXIDE_STAIN, 0.56) + steelDetail * 0.84, 0.0, 1.0);
        ceilingColor = mix(ceilingColor, stained, stain * 0.27);
        if (amount > 0.16) {
          vec3 oxide = mix(OXIDE_DARK, OXIDE_MID, smoothstep(0.22, 0.62, amount));
          oxide = mix(oxide, OXIDE_WARM, smoothstep(0.58, 0.90, amount));
          oxide = mix(oxide, OXIDE_OCHRE, flake * 0.62);
          oxide = mix(oxide, OXIDE_PIT, pit * 0.76);
          float relief = bump * (0.07 + 0.07 * amount);
          float keepSteel = mix(0.74, 0.28, smoothstep(0.20, 0.88, amount));
          vec3 corroded = clamp(oxide + steelDetail * keepSteel + vec3(1.0, 0.58, 0.28) * relief, 0.0, 1.0);
          float rustBlend = smoothstep(0.16, 0.42, amount) * clamp(0.32 + amount * 0.58, 0.0, 1.0);
          ceilingColor = mix(ceilingColor, corroded, rustBlend);
        }
      }
    }
  }
  vec3 color = mix(base, ceilingColor, isCeiling);
  if (uHasPbr == 1)
    color = pbrShade(color * uMaterialDiffuse, lit, rustiness);
  else
    color *= uMaterialDiffuse * surfaceLight(vWorldPos, lit);
  color += vec3(0.04, 0.18, 0.24) * cyanGlow * (1.0 - isCeiling) * 0.45;
  float pitDepthFade = smoothstep(-2.0, -48.0, vWorldPos.y);
  vec3 pitFogColor = uHasFog == 1 ? uFogColor * 0.42 : vec3(0.02, 0.03, 0.06);
  color = mix(color, pitFogColor, pitDepthFade);
  if (uHasFog == 1) {
    float fade = clamp((vDepth - uFogNear) / (uFogFar - uFogNear), 0.0, 1.0);
    color = mix(color, uFogColor, fade);
  }
  gl_FragColor = vec4(color, 0.5);
}
